#!/bin/sh
set -eu

# @getoptions
ENVIRONMENT_TYPES='desktop | container'

parser_definition() {
  setup   REST help:usage -- "Usage: example.sh [options]... [arguments]..." ''
  msg -- 'Options:'
  option  ENVIRONMENT_TYPE  -e --environment-type pattern:"${ENVIRONMENT_TYPES}"  -- "${ENVIRONMENT_TYPES}"
  option  PREFERENCE_PATH   -p --preference-path  validate:file_exists            -- "preference file path"
  disp    :usage            -h --help
}

file_exists() {
  [ -f "${OPTARG}" ] && return 0 || return 1
}
# @end

# @gengetoptions parser -i parser_definition parse
